  1	import java.util.Arrays;
  2	
  3	public final class QuickSelect {
  4	
  5	    private static final PivotSelector DEFAULT_PIVOT_SELECTOR =
  6	        new MedianOfThreePivotSelector();
  7	
  8	    private QuickSelect() {
  9	        // Utility class.
 10	    }
 11	
 12	    public static int selectKthSmallest(int[] values, int rank) {
 13	        return SelectionRequest.copying(values, rank).createSession().select();
 14	    }
 15	
 16	    public static int selectKthSmallestInPlace(int[] values, int rank) {
 17	        return SelectionRequest.inPlace(values, rank).createSession().select();
 18	    }
 19	
 20	    public static int kthSmallest(int[] values, int k) {
 21	        return selectKthSmallest(values, k);
 22	    }
 23	
 24	    private static void swap(int[] values, int left, int right) {
 25	        if (left == right) {
 26	            return;
 27	        }
 28	
 29	        int temp = values[left];
 30	        values[left] = values[right];
 31	        values[right] = temp;
 32	    }
 33	
 34	    private static final class SelectionSession {
 35	
 36	        private final int[] values;
 37	        private final int targetIndex;
 38	        private final PivotSelector pivotSelector;
 39	        private int low;
 40	        private int high;
 41	
 42	        private SelectionSession(int[] values, int targetIndex, PivotSelector pivotSelector) {
 43	            this.values = values;
 44	            this.targetIndex = targetIndex;
 45	            this.pivotSelector = pivotSelector;
 46	            this.low = 0;
 47	            this.high = values.length - 1;
 48	        }
 49	
 50	        private int select() {
 51	            while (isSearchActive()) {
 52	                int partitionIndex = partitionCurrentRange();
 53	
 54	                if (partitionIndex == targetIndex) {
 55	                    return values[partitionIndex];
 56	                }
 57	
 58	                narrowSearchRange(partitionIndex);
 59	            }
 60	
 61	            throw new IllegalStateException("Quickselect failed to locate the target index");
 62	        }
 63	
 64	        private boolean isSearchActive() {
 65	            return low <= high;
 66	        }
 67	
 68	        private int partitionCurrentRange() {
 69	            movePivotToEnd();
 70	            int pivot = values[high];
 71	            int pivotIndex = low;
 72	
 73	            for (int i = low; i < high; i++) {
 74	                if (values[i] < pivot) {
 75	                    swap(values, i, pivotIndex);
 76	                    pivotIndex++;
 77	                }
 78	            }
 79	
 80	            swap(values, high, pivotIndex);
 81	            return pivotIndex;
 82	        }
 83	
 84	        private void movePivotToEnd() {
 85	            swap(values, pivotSelector.selectPivotIndex(values, low, high), high);
 86	        }
 87	
 88	        private void narrowSearchRange(int partitionIndex) {
 89	            if (partitionIndex < targetIndex) {
 90	                low = partitionIndex + 1;
 91	            } else {
 92	                high = partitionIndex - 1;
 93	            }
 94	        }
 95	    }
 96	
 97	    private static final class SelectionRequest {
 98	
 99	        private final int[] values;
100	        private final int targetIndex;
101	
102	        private SelectionRequest(int[] values, int targetIndex) {
103	            this.values = values;
104	            this.targetIndex = targetIndex;
105	        }
106	
107	        private static SelectionRequest copying(int[] values, int rank) {
108	            validateRank(values, rank);
109	            return new SelectionRequest(Arrays.copyOf(values, values.length), rank - 1);
110	        }
111	
112	        private static SelectionRequest inPlace(int[] values, int rank) {
113	            validateRank(values, rank);
114	            return new SelectionRequest(values, rank - 1);
115	        }
116	
117	        private SelectionSession createSession() {
118	            return new SelectionSession(values, targetIndex, DEFAULT_PIVOT_SELECTOR);
119	        }
120	    }
121	
122	    private interface PivotSelector {
123	
124	        int selectPivotIndex(int[] values, int low, int high);
125	    }
126	
127	    private static final class MedianOfThreePivotSelector implements PivotSelector {
128	
129	        @Override
130	        public int selectPivotIndex(int[] values, int low, int high) {
131	            int mid = low + (high - low) / 2;
132	
133	            order(values, low, mid);
134	            order(values, low, high);
135	            order(values, mid, high);
136	
137	            return mid;
138	        }
139	
140	        private static void order(int[] values, int left, int right) {
141	            if (values[left] > values[right]) {
142	                swap(values, left, right);
143	            }
144	        }
145	    }
146	
147	    private static void validateRank(int[] values, int rank) {
148	        if (values == null) {
149	            throw new IllegalArgumentException("Input array must not be null");
150	        }
151	
152	        if (values.length == 0) {
153	            throw new IllegalArgumentException("Input array must not be empty");
154	        }
155	
156	        if (rank < 1 || rank > values.length) {
157	            throw new IllegalArgumentException(
158	                "rank must be between 1 and " + values.length + " inclusive");
159	        }
160	    }
161	
162	    public static void main(String[] args) {
163	        QuickSelectDemo.main(args);
164	    }
165	}
